INSERT INTO `tb_aktivitas` VALUES (1,1,'Pengiriman Kayu Manis Raw Material ke Pabrik di Medan','Shipment of Raw Cinnamon Material to Factory in Medan','pengiriman-kayu-manis-raw-material-medan','shipment-raw-cinnamon-material-medan','Pengiriman kayu manis berkualitas tinggi ke pabrik di Medan.','High-quality cinnamon shipment to a factory in Medan.','Kami mengirimkan kayu manis mentah berkualitas tinggi langsung dari petani lokal ke pabrik di Medan, memastikan kesegaran dan kualitas terbaik.','We ship high-quality raw cinnamon directly from local farmers to a factory in Medan, ensuring freshness and top quality.','aktivitas (1).jpeg','Kayu manis siap dikirim ke pabrik','Cinnamon ready for shipment to factory','Pengiriman Kayu Manis','Cinnamon Shipping','Kayu manis mentah berkualitas tinggi dari Indonesia untuk industri.','High-quality raw cinnamon from Indonesia for the industry.','2025-02-08 03:51:47','2025-02-08 03:51:47'),(2,2,'Pengecekan Pohon Kayu Manis yang Terkena Hama','Inspection of Cinnamon Trees Affected by Pests','pengecekan-pohon-kayu-manis-terkena-hama','inspection-cinnamon-trees-affected-pests','Pengecekan pohon kayu manis untuk memastikan kualitas dan kesehatan tanaman.','Inspection of cinnamon trees to ensure plant quality and health.','Di Indonesian Export, kami melakukan pengecekan rutin pada pohon kayu manis untuk mendeteksi hama dan memastikan kualitas terbaik. Proses ini penting dalam menjaga standar ekspor dan keberlanjutan hasil panen.','At Indonesian Export, we conduct regular inspections of cinnamon trees to detect pests and ensure top quality. This process is crucial in maintaining export standards and sustainable harvests.','aktivitas (2).jpeg','Pengecekan hama pada pohon kayu manis','Pest inspection on cinnamon trees','Pengecekan Kualitas Kayu Manis','Cinnamon Quality Inspection','Pengecekan pohon kayu manis secara berkala untuk menjaga kualitas dan hasil panen.','Regular inspection of cinnamon trees to maintain quality and yield.','2025-02-08 03:51:47','2025-02-08 03:51:47'),(3,3,'Kunjungan Para Eksportir Rempah dari Jakarta\r\n','Visit of Spice Exporters from Jakarta\r\n','kunjungan-eksportir-rempah-jakarta','visit-spice-exporters-jakarta','Eksportir rempah dari Jakarta mengunjungi kebun dan fasilitas produksi kami.','Spice exporters from Jakarta visited our plantations and production facilities.','Indonesian Exporter menerima kunjungan eksportir rempah dari Jakarta untuk melihat langsung proses budidaya, panen, dan pengolahan rempah sebelum diekspor ke pasar global.','Indonesian Exporter welcomed spice exporters from Jakarta to observe firsthand the cultivation, harvesting, and processing of spices before export to global markets.','aktivitas (3).jpg','Eksportir rempah mengunjungi kebun dan fasilitas produksi','Spice exporters visiting plantations and production facilities','Kunjungan Eksportir Rempah','Visit of Spice Exporters','Eksportir rempah dari Jakarta melihat langsung proses budidaya dan produksi.','Spice exporters from Jakarta observed the cultivation and production process.','2025-02-08 03:51:47','2025-02-08 03:51:47'),(4,3,'Pengalaman Panen Kayu Manis','Cinnamon Harvesting Experience','pengalaman-panen-kayu-manis','cinnamon-harvesting-experience','Mengupas pengalaman langsung dalam panen kayu manis dari perkebunan.','Sharing firsthand experience in harvesting cinnamon from plantations.','Nikmati pengalaman panen kayu manis asli di perkebunan kayu manis! Dalam perjalanan ini, Anda akan diajak menjelajahi kebun yang rimbun, mempelajari teknik panen tradisional, dan melihat langsung proses dari kulit kayu hingga menjadi rempah aromatik yang ','Enjoy an authentic cinnamon harvest experience at a cinnamon farm! On this journey, you will be taken through lush gardens, learn traditional harvesting techniques, and see firsthand the process from bark to the aromatic spice we enjoy every day.','aktivitas (4).png','Proses panen kayu manis di perkebunan','Cinnamon harvesting process at the plantation','Pengalaman Panen Kayu Manis','Cinnamon Harvesting Experience','Ikuti pengalaman panen kayu manis langsung dari perkebunan lokal.','Join the experience of harvesting cinnamon directly from local plantations.','2025-02-08 03:51:47','2025-02-08 03:51:47');
