DROP TABLE IF EXISTS `tb_history_export_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_history_export_supplier` (
  `id_history` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `id_supplier` int(10) unsigned NOT NULL,
  `tahun` smallint(5) unsigned NOT NULL,
  `produk` varchar(255) DEFAULT NULL,
  `negara_tujuan` varchar(150) DEFAULT NULL,
  `jenis_ekspor` varchar(255) DEFAULT NULL,
  `kuantitas` varchar(255) DEFAULT NULL,
  `nilai_ekspor_usd` decimal(15,2) DEFAULT NULL,
  `nilai_ekspor_asli` varchar(100) DEFAULT NULL,
  `catatan` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id_history`),
  KEY `id_supplier_tahun` (`id_supplier`,`tahun`),
  CONSTRAINT `tb_history_export_supplier_id_supplier_foreign` FOREIGN KEY (`id_supplier`) REFERENCES `tb_supplier` (`id_supplier`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

