INSERT INTO `tb_kategori_produk` VALUES (1,'Rempah','Spices','rempah','spices','Kategori Rempah - Indonesian Exporter','Spices Category - Indonesian Exporter','Produk rempah-rempah berkualitas ekspor dari Indonesia.','High-quality export spices from Indonesia.','2025-11-13 14:09:36','2025-11-13 14:09:36'),(2,'Buah','Fruits','buah','fruits','Kategori Buah - Indonesian Exporter','Fruits Category - Indonesian Exporter','Berbagai buah tropis segar untuk ekspor.','Fresh tropical fruits for export.','2025-11-13 14:09:36','2025-11-13 14:09:36'),(3,'Sayur','Vegetables','sayur','vegetables','Kategori Sayur - Indonesian Exporter','Vegetables Category - Indonesian Exporter','Sayur mayur segar hasil pertanian Indonesia.','Fresh vegetables from Indonesian farms.','2025-11-13 14:09:36','2025-11-13 14:09:36'),(4,'Daun','Leaves','daun','leaves','Kategori Daun - Indonesian Exporter','Leaves Category - Indonesian Exporter','Beragam daun alami untuk keperluan industri dan konsumsi.','Various natural leaves for industrial and culinary use.','2025-11-13 14:09:36','2025-11-13 14:09:36'),(5,'Minuman','Beverage','minuman','beverage','Kategori Minuman - Indonesian Exporter ','Beverage Category - Indonesian Exporter','Produk minuman berkualitas ekspor dari indonesia ','High-quality export drinks from Indonesia ','2025-11-18 16:01:50','2025-11-20 09:41:23'),(6,'Camilan','Snack ','camilan','snack-','Kategori Camilan - Indonesian Exporter','Snack Category - Indonesia Exporter ','Produk camilan berkualitas ekspor dari Indonesia','High-quality export snack from indonesia ','2025-11-19 12:08:54','2025-11-19 12:08:54'),(7,'Produk Rumah Tangga','Household Product','produk-rumah-tangga','household-product','Produk Rumah Tangga','Household Product','Produk Rumah Tangga menghadirkan perlengkapan rumah tangga berkualitas untuk penggunaan harian yang praktis dan tahan lama.','Household Product offers quality household items designed for practical and durable everyday use.','2025-11-25 14:47:54','2025-11-25 14:48:52'),(8,'Produk Perawatan Pribadi','Personal Care Product','produk-perawatan-pribadi','personal-care-product','Produk Perawatan Pribadi','Personal Care Product','Produk Perawatan Pribadi berkualitas untuk menjaga kebersihan, kenyamanan, dan kesehatan tubuh Anda setiap hari.','High-quality Personal Care Products designed to support your daily hygiene, comfort, and body wellness.','2025-11-25 14:53:30','2025-11-25 14:53:30');
