INSERT INTO `tb_meta` VALUES (1,'Home','Beranda','Halaman Beranda','Home Page','Indonesian Exporter | Ekspor Rempah Indonesia ke Pasar Glob','Indonesian Exporter | Exporting Indonesian Spices to the Gl','Indonesian Exporter menyediakan layanan ekspor rempah dan produk Indonesia berkualitas ke pasar global.\r\n','Indonesian Exporter provides export services for quality Indonesian spices and products to the global market.'),(2,'About','Tentang','Pelajari visi, misi, dan komitmen Indonesian Exporter dalam mendukung ekspor rempah dan produk Indonesia ke pasar global.','Learn about Indonesian Exporter\'s vision, mission, and commitment to supporting the export of Indonesian spices and products to global markets.','Tentang Indonesian Exporter | Solusi Ekspor ke Pasar Global','About Indonesian Exporter | Export Solutions for Global Mar','Indonesian Exporter berkomitmen mendukung ekspor rempah dan produk Indonesia dengan layanan profesional dan terpercaya.','Indonesian Exporter is committed to supporting the export of Indonesian spices and products with professional and reliable services.'),(3,'Product','Produk','Temukan berbagai produk ekspor unggulan dari Indonesia, mulai dari rempah-rempah berkualitas tinggi hingga produk pertanian dan hasil alam terbaik.','Discover a wide range of premium Indonesian export products, from high-quality spices to top agricultural and natural commodities.','Produk Ekspor Indonesia','Indonesian Export Products','Jelajahi produk ekspor Indonesia berkualitas tinggi, termasuk rempah-rempah, hasil bumi, dan komoditas unggulan lainnya.','Explore high-quality Indonesian export products, including spices, agricultural goods, and top natural commodities.'),(4,'Activity','Aktivitas','Ikuti berbagai aktivitas dan inisiatif Indonesian Exporter, mulai dari pameran dagang, program pelatihan ekspor, hingga kolaborasi dengan mitra bisnis global.','Stay updated with Indonesian Exporter’s activities, from trade exhibitions and export training programs to collaborations with global business partners.','Aktivitas & Program Indonesian Exporter','Indonesian Exporter Activities & Programs','Dapatkan informasi terbaru tentang aktivitas Indonesian Exporter, termasuk pameran dagang, pelatihan, dan kolaborasi ekspor global.','Get the latest updates on Indonesian Exporter’s activities, including trade fairs, training programs, and global export collaborations.'),(5,'Article','Artikel','Dapatkan wawasan mendalam dan informasi terbaru tentang industri ekspor Indonesia.','Get in-depth insights and the latest information on Indonesia\'s export industry.','Artikel Indonesian Exporter | Ekspor & Perdagangan','Indonesian Exporter Articles | Export & Trade','Temukan artikel informatif tentang ekspor, perdagangan internasional, dan peluang bisnis global bersama Indonesian Exporter.','Discover insightful articles on exports, international trade, and global business opportunities with Indonesian Exporter.'),(6,'Contact','Kontak','Hubungi Indonesian Exporter untuk informasi lebih lanjut mengenai ekspor, perdagangan internasional, dan kemitraan bisnis. Tim kami siap membantu Anda.','Contact Indonesian Exporter for more information about exports, international trade, and business partnerships. Our team is ready to assist you.','Hubungi Indonesian Exporter | Konsultasi Ekspor','Contact Indonesian Exporter | Export Consultation','Dapatkan informasi ekspor dan perdagangan global dengan menghubungi tim Indonesian Exporter. Kami siap membantu kebutuhan bisnis Anda.','Get export and global trade information by contacting the Indonesian Exporter team. We are ready to assist your business needs.'),(7,'Product Detail','Detail Produk','Temukan informasi lengkap tentang produk ekspor unggulan Indonesia','Discover complete information about Indonesia\'s top export products','Detail Produk','Product Detail','Lihat deskripsi lengkap produk Indonesian Exporter.','View the full description of the Indonesian Exporter product.'),(8,'Activity Detail','Detail Aktivitas','Halaman ini menyajikan aktivitas Indonesian Exporter untuk memberikan wawasan bermanfaat.','This page presents Indonesian Exporter activities to provide useful insights.','Detail Aktivitas','Activity Detail','Halaman Detail Aktivitas.','Activity Detail Page.'),(9,'Article Detail','Detail Artikel','Baca artikel lengkap tentang ekspor, perdagangan global, dan inovasi industri dengan informasi mendalam dan wawasan bermanfaat.','Read full articles on exports, global trade, and industry innovations with in-depth information and valuable insights.','Detail Artikel','Article Detail','Temukan artikel lengkap tentang ekspor dan perdagangan global hanya di Indonesian Exporter.','Explore full articles on exports and global trade exclusively on Indonesian Exporter.');
/*!40000 ALTER TABLE `tb_meta` ENABLE KEYS */;
