DROP TABLE IF EXISTS `tb_produk_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_produk_supplier` (
  `id_produk_supplier` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `id_supplier` int(10) unsigned NOT NULL,
  `nama_produk` varchar(255) NOT NULL,
  `spesifikasi` text DEFAULT NULL,
  `kapasitas_produksi` text DEFAULT NULL,
  `legalitas` text DEFAULT NULL,
  `sertifikasi` text DEFAULT NULL,
  `lokasi_barang` varchar(255) DEFAULT NULL,
  `foto_1` varchar(500) DEFAULT NULL,
  `foto_2` varchar(500) DEFAULT NULL,
  `foto_3` varchar(500) DEFAULT NULL,
  `foto_4` varchar(500) DEFAULT NULL,
  `foto_5` varchar(500) DEFAULT NULL,
  `moq` varchar(255) DEFAULT NULL,
  `harga_exw` text DEFAULT NULL,
  `komisi` varchar(255) DEFAULT NULL,
  `sudah_ekspor` varchar(100) DEFAULT NULL,
  `views` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id_produk_supplier`),
  KEY `nama_produk` (`nama_produk`),
  KEY `id_supplier` (`id_supplier`),
  CONSTRAINT `tb_produk_supplier_id_supplier_foreign` FOREIGN KEY (`id_supplier`) REFERENCES `tb_supplier` (`id_supplier`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

